use matmul::multiply;

#[test]
fn test_2x2() {
    let a = vec![vec![1, 2], vec![3, 4]];
    let b = vec![vec![5, 6], vec![7, 8]];
    let c = multiply(&a, &b);
    assert_eq!(c, vec![vec![19, 22], vec![43, 50]]);
}

#[test]
fn test_identity() {
    let a = vec![vec![1i64, 2], vec![3, 4]];
    let id = vec![vec![1i64, 0], vec![0, 1]];
    assert_eq!(multiply(&a, &id), a);
}

#[test]
fn test_nonsquare() {
    let a = vec![vec![1, 2, 3], vec![4, 5, 6]];
    let b = vec![vec![7, 8], vec![9, 10], vec![11, 12]];
    let c = multiply(&a, &b);
    assert_eq!(c, vec![vec![58, 64], vec![139, 154]]);
}

#[test]
fn test_1x1() {
    let a = vec![vec![6_i64]];
    let b = vec![vec![7_i64]];
    assert_eq!(multiply(&a, &b), vec![vec![42_i64]]);
}

#[test]
fn test_zeros() {
    let a = vec![vec![0i64, 0], vec![0, 0]];
    let b = vec![vec![1i64, 2], vec![3, 4]];
    assert_eq!(multiply(&a, &b), vec![vec![0i64, 0], vec![0, 0]]);
}

